// sverity-args: --top top --sdc @FIXTURES@/_common/async.sdc
// The destination reset rst_b is generated by logic, so its source is unresolved. Destination tolerance is not proved, so the obligation stays visible at WARNING.
// expect: RDC-005 WARNING
// expect-count: RDC-005 WARNING 1
// expect-coverage: reset-extraction INCOMPLETE
module top(input logic clka, clkb, rst_a, rst_c, d, output logic q);
  logic s, t, rst_b;
  assign rst_b = rst_a & rst_c;
  always_ff @(posedge clka or negedge rst_a) if (!rst_a) s <= 1'b0; else s <= d;
  always_ff @(posedge clkb or negedge rst_b) if (!rst_b) t <= 1'b0; else t <= s;
  assign q = t;
endmodule
